			Object[] getValues() {
				if (not(value))
					return blank.Obj;
				try {
					ResultSetMetaData metadata = value.getMetaData();
					int numberOfCols = metadata.getColumnCount();
					arr values = new arr();
					for (int i = 1; i <= numberOfCols; i++) {
						values.add(value.getObject(i));
					}
					return values.array();
				} catch (SQLException e) {
					return blank.Obj;
				}
			}
			Object[] values() {
				return getValues();
			}
