	public static class money {
		public money khud = this, ka = this, iske_lie = khud, iska = khud,
				isko = khud, self = khud;
		public KL parent = kl();
		//@class.why: this class is supposed to help deal with money-related everyday calculations easier (currency conversion will be added soon)
		private double amnt;
		private String cur;
		money() {
			this.amnt = 0;
			this.cur = "Rs. ";
		}
		money(double amnt) {
			this.amnt = not(amnt) ? 0 : amnt;
			this.cur = "Rs. ";
		}
		money(double amnt, String cur) {
			this.amnt = not(amnt) || isInf(amnt) ? 0 : amnt;
			this.cur = not(this.cur) || len(this.cur) < 1 || len(this.cur) > 4
					? "Rs. "
					: titleCase(cur);
		}
		money cur(String newCurrency) {
			this.cur = not(newCurrency) || len(newCurrency) < 1
					|| len(newCurrency) > 4 ? "Rs. " : titleCase(newCurrency);
			return this;
		}
		money currency(String newCurrency) {
			cur(newCurrency);
			return this;
		}
		money setCur(String newCurrency) {
			cur(newCurrency);
			return this;
		}
		money setCurrency(String newCurrency) {
			cur(newCurrency);
			return this;
		}
		money amount(double newAmnt) {
			this.amnt = isInf(newAmnt) ? this.amnt : newAmnt;
			return this;
		}
		money setAmount(double newAmnt) {
			amount(newAmnt);
			return this;
		}
		money add(double... nums) {
			each(nums, n -> this.amnt += n);
			return this;
		}
		money give(double... nums) {
			add(nums);
			return this;
		}
		money plus(double... nums) {
			add(nums);
			return this;
		}
		money deposit(double... nums) {
			add(nums);
			return this;
		}
		money minus(double... nums) {
			each(nums, n -> this.amnt -= n);
			return this;
		}
		money take(double... nums) {
			minus(nums);
			return this;
		}
		money sub(double... nums) {
			minus(nums);
			return this;
		}
		money withdraw(double... nums) {
			minus(nums);
			return this;
		}
		money times(double... nums) {
			each(nums, n -> this.amnt *= n);
			return this;
		}
		money mul(double... nums) {
			times(nums);
			return this;
		}
		money div(double... nums) {
			each(nums, n -> {
				if (n == 0)
					n = (double) 1.0;
				this.amnt /= n;
			});
			return this;
		}
		money quotient(double... nums) {
			div(nums);
			return this;
		}
		public String suffix(boolean... bools) {
			boolean forceInternational = bools != null && bools.length > 0
					? bools[0]
					: false;
			this.cur = trim(this.cur) + " ";
			if (in(this.cur, "pk|in|rs")) {
				return "Rs. " + (forceInternational
						? ussuffix(amnt)
						: pksuffix(amnt));
			}
			if (in(this.cur, "us")) {
				return "USD " + ussuffix(amnt);
			}
			return this.cur + (forceInternational
					|| (is(this.cur) && !in(this.cur, "pk|in|rs"))
							? ussuffix(amnt)
							: pksuffix(amnt));
		}
		@Override
		public String toString() {
			this.cur = trim(this.cur) + " ";
			if (not(this.cur) || in(this.cur, "pk|in|rs")) {
				return pkr(amnt);
			}
			if (in(this.cur, "us")) {
				return usd(amnt);
			}
			return this.cur + f(amnt);
		}
		public String toString(boolean suffixMode) {
			return suffixMode ? suffix() : toString();
		}
		public String string() {
			return toString();
		}
		public String str() {
			return string();
		}
		public String string(boolean suffixMode) {
			return toString(suffixMode);
		}
		public String str(boolean suffixMode) {
			return string(suffixMode);
		}
		public String balance() {
			return toString();
		}
		public String balance(boolean suffixMode) {
			return toString(suffixMode);
		}
		public String bal() {
			return toString();
		}
		public String bal(boolean suffixMode) {
			return toString(suffixMode);
		}
		public String total() {
			return toString();
		}
		public String total(boolean suffixMode) {
			return toString(suffixMode);
		}
	}
