	public static String encode(String s) {
		try {
			return Base64.getEncoder().encodeToString(s.getBytes());
		} catch (Exception e) {
			return "";
		}
	}
	public static String cypher(String s) {
		return encode(s);
	}
	public static String lock(String s) {
		return encode(s);
	}
	public static String encode(String s, Object salt) {
		return encrypt(s, salt);
	}
	public static String cypher(String s, Object salt) {
		return encrypt(s, salt);
	}
	public static String lock(String s, Object salt) {
		return encrypt(s, salt);
	}
	public static String decode(String s) {
		try {
			return new String(Base64.getDecoder().decode(s));
		} catch (Exception e) {
			return "";
		}
	}
	public static String decypher(String s) {
		return decode(s);
	}
	public static String unlock(String s) {
		return decode(s);
	}
	public static String decode(String s, Object salt) {
		return decrypt(s, salt);
	}
	public static String decypher(String s, Object salt) {
		return decrypt(s, salt);
	}
	public static String unlock(String s, Object salt) {
		return decrypt(s, salt);
	}
	public static String encodeUrl(String s) {
		if (not(s))
			return "";
		String encoded = s.replace("%", "%25").replace(" ", "%20")
				.replace("!", "%21").replace("#", "%23").replace("$", "%24")
				.replace("&", "%26").replace("'", "%27").replace("(", "%28")
				.replace(")", "%29").replace("*", "%2A").replace("+", "%2B")
				.replace(",", "%2C").replace("/", "%2F").replace(":", "%3A")
				.replace(";", "%3B").replace("=", "%3D").replace("?", "%3F")
				.replace("@", "%40").replace("[", "%5B").replace("]", "%5D");
		return encoded;
	}
	public static String decodeUrl(String s) {
		if (not(s))
			return "";
		String decoded = s.replace("%21", "!").replace("%20", " ")
				.replace("%23", "#").replace("%24", "$").replace("%26", "&")
				.replace("%27", "'").replace("%28", "(").replace("%29", ")")
				.replace("%2A", "*").replace("%2B", "+").replace("%2C", ",")
				.replace("%2F", "/").replace("%3A", ":").replace("%3B", ";")
				.replace("%3D", "=").replace("%3F", "?").replace("%40", "@")
				.replace("%5B", "[").replace("%5D", "]").replace("%25", "%");
		return decoded;
	}
	public static String encrypt(String data, Object salt) {
		if (not(data) || isNull(salt))
			return "";
		String key = Str(salt);
		final String ofXAlgo = "AES";
		try {
			SecretKeySpec secretKey = new SecretKeySpec(
					key.getBytes(StandardCharsets.UTF_8), ofXAlgo);
			Cipher cipher = Cipher.getInstance(ofXAlgo);
			cipher.init(Cipher.ENCRYPT_MODE, secretKey);
			byte[] encryptedBytes = cipher
					.doFinal(data.getBytes(StandardCharsets.UTF_8));
			return Base64.getEncoder().encodeToString(encryptedBytes);
		} catch (Exception err) {
			return data;
		}
	}
	public static String decrypt(String encryptedData, Object salt) {
		if (not(encryptedData) || isNull(salt))
			return "";
		String key = Str(salt);
		final String ofXAlgo = "AES";
		try {
			SecretKeySpec secretKey = new SecretKeySpec(
					key.getBytes(StandardCharsets.UTF_8), ofXAlgo);
			Cipher cipher = Cipher.getInstance(ofXAlgo);
			cipher.init(Cipher.DECRYPT_MODE, secretKey);
			byte[] decryptedBytes = cipher
					.doFinal(Base64.getDecoder().decode(encryptedData));
			return new String(decryptedBytes, StandardCharsets.UTF_8);
		} catch (Exception err) {
			print("[KL.Decryptor.BadArguments]:\nFailed to decrypt the message.");
			return "";
		}
	}
