		public app state(String newState) {
			switch (newState) {
				case "min" :
					super.setExtendedState(super.ICONIFIED);
					break;
				case "max" :
					super.setExtendedState(super.MAXIMIZED_BOTH);
					break;
				default :
					super.setExtendedState(super.NORMAL);
			}
			return this;
		}
		public String state() {
			int x = super.getExtendedState();
			String state = x == super.NORMAL
					? "normal"
					: x == super.ICONIFIED
							? "minimized"
							: x == super.MAXIMIZED_BOTH
									? "maximized"
									: "unknown";
			return state;
		}
		public app min() {
			state("min");
			return this;
		}
		public app max() {
			state("max");
			return this;
		}
