	public static class btnGroup extends ButtonGroup {
		public btnGroup khud = this, ka = this, iske_lie = khud, iska = khud,
				isko = khud, self = khud;
		public ButtonGroup parent = new ButtonGroup();
		btnGroup() {
			super();
		}
		btnGroup(AbstractButton... buttons) {
			super();
			addAll(buttons);
		}
		btnGroup add(AbstractButton... buttons) {
			if (buttons == null || buttons.length == 0)
				return this;
			for (AbstractButton button : buttons) {
				if (button == null)
					continue;
				super.add(button);
			}
			return this;
		}
		btnGroup addAll(AbstractButton... buttons) {
			this.add(buttons);
			return this;
		}
		btnGroup remove(AbstractButton... buttons) {
			if (buttons == null || buttons.length == 0)
				return this;
			for (AbstractButton button : buttons) {
				if (button == null)
					continue;
				super.remove(button);
			}
			return this;
		}
		btnGroup removeAll(AbstractButton... buttons) {
			this.remove(buttons);
			return this;
		}
	}
