		tree<Key, Value> slice(int start) {
			if (super.isEmpty()) {
				return new tree<>();
			}
			if (start < 0) {
				start = 0;
			}
			if (start >= super.size()) {
				return new tree<>();
			}
			tree<Key, Value> subMap = new tree<>();
			int index = 0;
			for (Key key : super.keySet()) {
				if (index >= start) {
					subMap.put(key, super.get(key));
				}
				index++;
			}
			return subMap;
		}
		tree<Key, Value> slice(int start, int end) {
			if (super.isEmpty()) {
				return new tree<>();
			}
			if (start < 0) {
				start = 0;
			}
			if (end > super.size()) {
				end = super.size();
			}
			if (start > end) {
				int temp = start;
				start = end;
				end = temp;
			}
			tree<Key, Value> subMap = new tree<>();
			int index = 0;
			for (Key key : super.keySet()) {
				if (index >= start && index < end) {
					subMap.put(key, super.get(key));
				}
				index++;
			}
			return subMap;
		}
