		public static int[] inclusive(int n) {
			intArr arr = intArr();
			if (not(n) || isInf(n)) {
				return arr.array();
			}
			if (n > 0) {
				for (int i = 0; i <= n; i++) {
					arr.add(i);
				}
			} else {
				for (int i = 0; i >= n; i--) {
					arr.add(i);
				}
			}
			return arr.array();
		}
		public static double[] inclusive(double n) {
			dblArr arr = blank.dblArr;
			if (not(n)) {
				return arr.array();
			}
			if (n > 0) {
				for (double i = 0; i <= n; i += .1) {
					arr.add(i);
				}
			} else {
				for (double i = 0; i >= n; i -= .1) {
					arr.add(i);
				}
			}
			return arr.array();
		}
