	public static int[] range(int n) {
		intArr arr = intArr();
		if (not(n) || isInf(n)) {
			return arr.array();
		}
		if (n > 0) {
			for (int i = 0; i < n; i++) {
				arr.add(i);
			}
		} else {
			for (int i = 0; i > n; i--) {
				arr.add(i);
			}
		}
		return arr.array();
	}
	public static double[] range(double n) {
		dblArr arr = blank.dblArr;
		if (not(n)) {
			return arr.array();
		}
		if (n > 0) {
			for (double i = 0; i < n; i += .1) {
				arr.add(i);
			}
		} else {
			for (double i = 0; i > n; i -= .1) {
				arr.add(i);
			}
		}
		return arr.array();
	}
	public static int[] range(int m, int n, int... optional) {
		intArr arr = intArr();
		if (isNull(m) || isNull(n) || eq(m, n)) {
			return arr.array();
		}
		int step = 1;
		if (is(optional) && len(optional) == 1) {
			step = is(optional[0]) && !isNeg(optional[0]) && !isInf(optional[0])
					? optional[0]
					: 1;
		}
		if (m > n) {
			for (int i = m; i >= n; i -= step) {
				arr.add(i);
			}
		} else {
			for (int i = m; i <= n; i += step) {
				arr.add(i);
			}
		}
		return arr.array();
	}
	public static String[] range(String m, String n, int... optional) {
		strArr arr = strArr();
		if (isNull(m) || isNull(n) || eq(m, n) || !eq(m, "[A-Za-z]")
				|| !eq(n, "[A-Za-z]")) {
			return arr.array();
		}
		int step = 1;
		if (is(optional) && len(optional) == 1) {
			step = is(optional[0]) && !isNeg(optional[0]) && !isInf(optional[0])
					? optional[0]
					: 1;
		}
		int charCodeOfM = m.charAt(0), charCodeOfN = n.charAt(0);
		if (charCodeOfM > charCodeOfN) {
			for (int i = charCodeOfM; i >= charCodeOfN; i -= step) {
				arr.add(Str((char) i));
			}
		} else {
			for (int i = charCodeOfM; i <= charCodeOfN; i += step) {
				arr.add(Str((char) i));
			}
		}
		return arr.array();
	}
