	public static String repeat(String s, int times) {
		if (not(s) || not(times) || isNeg(times) || isInfinity(times)) {
			return s;
		}
		String org = s;
		for (; -1 + times > 0; times--) {
			s += org;
		}
		return s;
	}
	public static String times(String s, int n) {
		return repeat(s, n);
	}
	public static String repeat(String s) {
		return repeat(s, 2);
	}
	public static String fill(String s, int n) {
		return repeat(s, n);
	}
	public static char[] map(char[] arr, Function<Character, Character> func) {
		if (not(arr) || not(func)) {
			return arr;
		}
		char[] result = new char[arr.length];
		for (int i = 0; i < arr.length; i++) {
			result[i] = func.apply(arr[i]);
		}
		return result;
	}
