	public static void println(Object... args) {
		if (args == none || len(args) == 0) {
			return;
		}
		String breakCharacter;
		if (isStr(args[0]) && in(as(_s, args[0]), "^\\W{0,1}$")) {
			breakCharacter = as(_s, args[0]);
			args = slice(args, 1);
		} else {
			if (isNull(printSettings.breakCharacter))
				printSettings.breakCharacter = "";
			if (isNull(args[0]))
				breakCharacter = "";
			else
				breakCharacter = printSettings.breakCharacter;
		}
		if (!isNull(args[0]) && args[0] instanceof String && in(Str(args[0]),
				"[\\$\\%\\&\\{\\}]|\\d(?=[Ee][\\+\\-]?\\d)")) {
			if (len(args) >= 2) {
				new KL().printf((String) args[0], slice(args, 1));
				return;
			} else {
				new KL().printf((String) args[0], '\0', "", 0, 0L, 0F, 0D, No);
				return;
			}
		}
		if (len(args) == 1 && !isNull(args[0]) && isArr(args[0])) {
			printArr(args[0]);
			return;
		} else {
			int count = 0;
			for (Object arg : args) {
				if (isNull(arg)) {
					arg = "none";
				}
				if (isArr(arg) || type(arg, "(str|int|long|flt|dbl|bool)Arr")) {
					printArr(arg);
					System.out.print(" ");
					continue;
				} else if (arg instanceof Character) {
					arg = "\'" + arg + "\'";
				} else if (arg instanceof Integer) {
					arg = fus((int) arg);
				} else if (arg instanceof Long) {
					arg = fus((long) arg) + "L";
				} else if (arg instanceof Float || arg instanceof Double) {
					boolean was_float = false;
					if (arg instanceof Float)
						was_float = true;
					arg = fus(
							arg instanceof Float ? (float) arg : (double) arg);
					if (was_float)
						arg += "F";
				} else if (type(arg, "^(o|tree)[A-Z]*$")) {
					if (arg instanceof o) {
						o parsedO = as(_o, arg);
						for (Object value : parsedO.array()) {
							if (value instanceof String[]) {
								//if string array
								String expandedStringValue = "[\"" + join(
										(String[]) value, "\", \"").replaceAll(
												"(?<=,)\\s*(\\s)\\s*(?=[\"\\w\\s\\.\\-]+$)",
												"$1and$1")
										+ "\"]";
								arg = Str(arg).replaceFirst(
										"\\[Ljava\\.lang\\.String;@\\w+",
										expandedStringValue);
							}
							if (value instanceof Character) {
								arg = Str(arg).replaceFirst(
										"\\b" + value + "\\b",
										"\'" + value + "\'");
							}
							if (value instanceof Long) {
								arg = Str(arg).replaceFirst(
										"\\b" + value + "\\b", value + "L");
							}
							if (value instanceof Float) {
								arg = Str(arg).replaceFirst(
										"\\b" + value + "\\b", value + "F");
							}
						}
					}
					arg = Str(arg).replaceAll(
							"(?<=\\=)((((\\d*[A-Za-z]{1,}\\d*)(\\s*[^,\\{\\}]+\\d*){0,}))|[A-Za-z]{1,}[^,\\{\\}]+|\\d+\\s*[^,\\d\\.,\\{\\}]+)",
							"\"$1\"")
							.replaceAll(
									"(?<=\\d[FfLl])\"|\"(?=\\d*\\.?\\d+[FfLL])",
									"")
							.replaceAll("\\[Ljava\\.lang\\.(\\w+);@\\w+",
									"\\<$1\\[\\]\\>")
							.replaceAll("\"true\"", "Yes")
							.replaceAll("\"false\"", "No")
							.replaceAll("=", ": ");
					String[] numericMatches = findMatches("" + arg,
							"(?<=\\w\\:\\s)\\-?\\d*\\.?\\d+");
					for (String numericMatch : numericMatches) {
						String formatted = fus(Dbl(numericMatch));
						arg = ("" + arg).replaceFirst(numericMatch, formatted);
					}
					// regex accuracy: 93%
					// changes needed: probably not
				} else if (arg instanceof Boolean) {
					o replacements = o("true=Yes, false=No");
					String preprocessed = replace(Str(arg), replacements);
					arg = preprocessed;
				}
				String result = (arg + breakCharacter).replaceAll("^\\s+", "");
				hint trimming_whitespace_in_case_any_seen_on_the_left;
				count++;
				if (count == len(args) && !eq(breakCharacter, " "))
					result = result.replaceAll(breakCharacter + "$", "");
				System.out.print(result);
			}
		}
	}
