	public static String concat(Object... args) {
		if (not(args)) {
			return "";
		}
		String result = "";
		for (var arg : args) {
			if (isNull(arg)) {
				continue;
			}
			result += ("" + arg);
		}
		return result;
	}
	public static String cat(Object... args) {
		return concat(args);
	}
