	public static String firstWord(String str) {
		String[] words = splitIntoWords(str);
		if (not(str) || words.length == 0)
			return "";
		return words[0];
	}
	public static String secWord(String str) {
		String[] words = splitIntoWords(str);
		if (not(str) || words.length == 0)
			return "";
		if (words.length < 2)
			return words[0];
		return words[1];
	}
	public static String secondWord(String str) {
		return secWord(str);
	}
	public static String secLastWord(String str) {
		String[] words = splitIntoWords(str);
		if (not(str) || words.length == 0)
			return "";
		if (words.length < 3)
			return words[0];
		return words[words.length - 2];
	}
	public static String secondLastWord(String str) {
		return secLastWord(str);
	}
	public static String lastWord(String str) {
		String[] words = splitIntoWords(str);
		if (not(str) || words.length == 0)
			return "";
		return words[words.length - 1];
	}
	public static String nthWord(String str, int i) {
		String[] words = splitIntoWords(str);
		if (not(str) || words.length == 0)
			return "";
		if (i >= str.length())
			return words[words.length - 1];
		if (i < 0) {
			i = Math.abs(i);
			if (i > 0 && i <= words.length)
				return nthLastWord(str, i);
			return words[0];
		}
		return words[i];
	}
	public static String nthLastWord(String str, int i) {
		String[] words = splitIntoWords(str);
		if (not(str) || words.length == 0)
			return "";
		if (i <= 0)
			return words[0];
		if (i > words.length)
			return words[words.length - 1];
		return words[words.length - i];
	}
	public static String shortestWord(String str) {
		String[] words = wordsOf(str);
		if (not(str) || words.length == 0)
			return "";
		String shortest = words[0];
		for (String currentWord : words) {
			if (currentWord.length() < shortest.length())
				shortest = currentWord;
		}
		return shortest;
	}
	public static String longestWord(String str) {
		String[] words = wordsOf(str);
		if (not(str) || words.length == 0)
			return "";
		String longest = words[0];
		for (String currentWord : words) {
			if (currentWord.length() > longest.length())
				longest = currentWord;
		}
		return longest;
	}
	public static String join(char[] arr, String with) {
		if (not(arr) || isNull(with)) {
			return "";
		}
		String returnValue = "";
		for (int i : range(arr))
			returnValue += arr[i] + with;
		returnValue = returnValue.replaceAll(with + "$", "");
		return returnValue;
	}
