	public static String join(char[] array) {
		if (not(array)) {
			return "";
		}
		String halfProcessed = join(array, ", ");
		String returnValue = replace(halfProcessed,
				"(?<=,)\\s*(\\s)\\s*(?=[\\w\\s\\.\\-]+$)", "$1and$1");
		// helps return a string in the American format of joining: e.g. a, b, and c
		// for
		// three items
		return returnValue;
	}
