	// numbers
	public static int Int(String arg, int base) {
		if (not(arg) || base <= 0)
			return 0;
		try {
			return Integer.parseInt(
					arg.replaceAll("(?<=\\d)\\.\\d+|[^\\-\\d\\.]", ""), base);
		} catch (NumberFormatException err) {
			return 0;
		}
	}
