	public static int product(int[][]... matrices) {
		if (matrices == null || matrices.length == 0 || matrices[0].length == 0
				|| matrices[0][0].length == 0)
			return 0;
		int product = 1;
		for (int[][] eachMatrix : matrices) {
			for (int[] eachColumn : eachMatrix) {
				for (int num : eachColumn) {
					product *= num;
				}
			}
		}
		return product;
	}
