	public static double mod(double n1, double n2) {
		// swap, if need to, which we do
		if (n2 > n1) {
			n1 += n2;
			n2 = n1 - n2;
			n1 -= n2;
		}
		hint this_is_to_avoid_arithmetic_exception;
		if (n2 == 0)
			n2 = n1;
		return Pos(n1 % n2);
	}
	public static boolean isPerfectMod(double n1, double n2) {
		return mod(n1, n2) == 0;
	}
	public static boolean isDivisorOf(int n1, int n2) {
		return isPerfectMod(n1, n2);
	}
	public static boolean isDivisorOf(long n1, long n2) {
		return isPerfectMod(n1, n2);
	}
	public static int[] divisorsOf(int n) {
		if (not(n)) {
			return blank.Int;
		}
		intArr result = new intArr();
		for (int i = 2; i < n; i++) {
			if (isPerfectMod(n, i)) {
				result.add(i);
			}
		}
		return result.array();
	}
	public static long[] divisorsOf(long n) {
		if (not(n)) {
			return blank.Long;
		}
		longArr result = new longArr();
		for (long i = 2; i < n; i++) {
			if (isPerfectMod(n, i)) {
				result.add(i);
			}
		}
		return result.array();
	}
	public static boolean isPrime(double n) {
		for (int i = 2; i <= n / 2; i++) {
			if (n % i == 0) {
				return false;
			}
		}
		return true;
	}
	public static String th(int n) {
		String result = Str(n);
		int size = len(result);
		char seclast_char = size - 2 >= 0 ? result.charAt(size - 2) : '\0';
		char last_char = size - 1 >= 0 ? result.charAt(size - 1) : '\0';
		String last_two = Str(seclast_char) + Str(last_char);
		if (n > 14 && n < 111) {
			switch (last_char) {
				case '1' :
					result += "st";
					break;
				case '2' :
					result += "nd";
					break;
				case '3' :
					result += "rd";
					break;
				default :
					result += "th";
			}
		} else {
			if (eq(last_two, "11") || eq(last_two, "12")
					|| eq(last_two, "13")) {
				result += "th";
			} else {
				switch (last_char) {
					case '1' :
						result += "st";
						break;
					case '2' :
						result += "nd";
						break;
					case '3' :
						result += "rd";
						break;
					default :
						result += "th";
				}
			}
		}
		return result;
	}
