	public static String pksuffix(int n) {
		n -= n % 1;
		String formattedN = fpkr(n);
		String[] parts = split(formattedN, ",");
		int size = len(parts);
		if (n < 800 || n > 99 * kh) {
			return formattedN;
		}
		String result = "";
		switch (size) {
			case 1 :
			case 2 :
				result = Str(n / hzr) + "hzr";
				break;
			case 3 :
				result = Str(n / lc) + "lc";
				break;
			case 4 :
				result = Str(n / cr) + "cr";
				break;
			case 5 :
				result = Str(n / ar) + "ar";
				break;
			case 6 :
				result = Str(n / kh) + "kh";
				break;
		}
		return result.replaceAll("\\.[0]+(?=[A-Za-z]{1,3}$)", "");
	}
