	public static String toRoman(int n) {
		treeI tree = new treeI();
		tree.add(1, "I").add(4, "IV").add(5, "V").add(9, "IX").add(10, "X")
				.add(40, "XL").add(50, "L").add(90, "XC").add(100, "C")
				.add(400, "CD").add(500, "D").add(900, "CM").add(1000, "M")
				.add(4000, "M_V").add(9000, "I_X").add(10000, "_X");
		int x = tree.floorKey(n);
		if (n != x) {
			return tree.get(x) + toRoman(n - x);
		}
		return tree.get(n);
	}
	public static int fibonacci(int n) {
		if (n <= 1)
			return n;
		int a = 0, b = 1;
		for (int i : range.inclusive(2, n)) {
			int sum = a + b;
			a = b;
			b = sum;
		}
		return b;
	}
	public static int[] fibonacciSequence(int n) {
		intArr result = intArr();
		for (int i : range.inclusive(n)) {
			result.push(fibonacci(i));
		}
		return result.array();
	}
	public static double percentage(double n1, double n2) {
		if (not(n1) || not(n2)) {
			return 0;
		}
		if (n1 <= n2) {
			// n1 is what percent of n2?
			// e.g. percentify(80, 800) should return 10
			return setPrecision(n1 / n2 * 100);
		} else {
			// need n2 percent of n1
			// e.g. percentify(800, 50) should return 400
			return setPrecision(n1 * n2 / 100);
		}
	}
	public static double percentify(double n1, double n2) {
		return percentage(n1, n2);
	}
