	public static String replaceNthWord(String str, String _with, int n) {
		if (not(str))
			return "";
		if (!wordsIn(str) || _with == null || n < 0 || n >= wordCount(str))
			return str;
		return replace(str, nthWord(str, n), _with);
	}
	public static String replace(String str, String to_replace,
			Function<String, String> fn) {
		if (not(str) || not(to_replace) || not(fn)) {
			return str;
		}
		StringBuilder s = new StringBuilder(str);
		Pattern p = Pattern.compile(to_replace);
		Matcher matcher = p.matcher(s);
		return matcher.replaceAll(m -> fn.apply(m.group()));
	}
	public static String replace(String str, o object) {
		if (not(str)) {
			return "";
		}
		if (not(object)) {
			return str;
		}
		String output = str;
		// for now
		for (String key : object.keys()) {
			if (!in(str, key))
				continue;
			output = output.replaceAll(key, Str(object.val(key)));
		}
		return output;
	}
