	public static boolean startsWith(String str, String re) {
		if (not(str) || not(re))
			return false;
		try {
			if (re.equals(".") || re.equals("*") || re.equals("+")
					|| re.equals("?") || re.equals("^") || re.equals("$")) {
				re = "\\" + re; // escape special characters IF they're the only
								// content of the regexp, to avoid stack overflow
			}
			Pattern pattern = Pattern.compile(
					"^(" + re.replaceAll("^\\^", "") + ")",
					Pattern.CASE_INSENSITIVE);
			Matcher matcher = pattern.matcher(str);
			return !!matcher.find();
		} catch (IllegalArgumentException | StackOverflowError e) {
			return false;
		}
	}
	public static boolean startsWith(String str, String re, int offset) {
		if (not(str) || not(re))
			return false;
		return startsWith(slice(str, offset), re);
	}
	public static boolean endsWith(String str, String re) {
		if (not(str) || not(re))
			return false;
		try {
			if (re.equals(".") || re.equals("*") || re.equals("+")
					|| re.equals("?") || re.equals("^") || re.equals("$")) {
				re = "\\" + re; // escape special characters IF they're the only
								// content of the regexp, to avoid stack overflow
			}
			Pattern pattern = Pattern.compile(
					"(" + re.replaceAll("\\$$", "") + ")$",
					Pattern.CASE_INSENSITIVE);
			Matcher matcher = pattern.matcher(str);
			return !!matcher.find();
		} catch (IllegalArgumentException | StackOverflowError e) {
			return false;
		}
	}
