	public static int indexOf(String str, char ch) {
		if (str == null || str.isEmpty() || ch == '\0')
			return -1;
		try {
			return str.indexOf(ch);
		} catch (Exception e) {
			return -1;
		}
	}
	public static int indexOf(String str, char ch, int start) {
		if (str == null || str.isEmpty() || ch == '\0' || start < 0
				|| start >= str.length())
			return -1;
		try {
			return str.indexOf(ch, start);
		} catch (Exception e) {
			return -1;
		}
	}
	public static int indexOf(String str, String re) {
		if (str == null || str.isEmpty())
			return -1;
		try {
			if (re.equals(".") || re.equals("*") || re.equals("+")
					|| re.equals("?") || re.equals("^") || re.equals("$")) {
				re = "\\" + re; // escape special characters IF they're the only
								// content of the regexp, to avoid stack overflow
			}
			Pattern p = Pattern.compile(re);
			Matcher m = p.matcher(str);
			if (!m.find())
				return -1;
			return m.start();
		} catch (IllegalArgumentException | StackOverflowError e) {
			return -1;
		}
	}
	public static int indexOf(String str, String re, int start) {
		if (re == null || str.isEmpty() || re.isEmpty() || start < 0
				|| start >= str.length())
			return -1;
		try {
			if (re.equals(".") || re.equals("*") || re.equals("+")
					|| re.equals("?") || re.equals("^") || re.equals("$")) {
				re = "\\" + re; // escape special characters IF they're the only
								// content of the regexp, to avoid stack overflow
			}
			Pattern p = Pattern.compile(re);
			Matcher m = p.matcher(str);
			m.region(start, str.length());
			if (!m.find())
				return -1;
			return m.start();
		} catch (IllegalArgumentException | StackOverflowError
				| IndexOutOfBoundsException e) {
			return -1;
		}
	}
