	public static boolean match(String str, String re, boolean... bools) {
		if (isNull(str) || isNull(re)) {
			return false;
		}
		// these null checks have to stay NULL checks, not entire `not` checks,
		// as not(re) would trim whitespace " ", which we sometimes DO need to
		// look up in a string to see if the string is more than one word, down
		// to ""
		if (re.equals(".") || re.equals("*") || re.equals("+") || re.equals("?")
				|| re.equals("^") || re.equals("$")) {
			re = "\\" + re; // escape special characters IF they're the only
							// content of the regexp, to avoid stack overflow
		}
		try {
			re = re.replaceAll("(?<![\\.\\\\])\\.(?![\\+\\*\\{])", "\\\\.")
					.replaceAll("(?<![\\\\\\.\\w\\)\\]\\|\\%\\$@])([\\+\\*])",
							"\\\\$1")
					.replaceAll("(?<!\\\\)%c", "[A-Za-z]")
					.replaceAll("(?<!\\\\)(%[sw]|\\{\\})", "[A-Za-z][\\\\w]+")
					.replaceAll("(?<!\\\\)%b", "(true|false)")
					.replaceAll("(?<!\\\\)%[di]", "(?<!\\.)\\\\d+(?!\\.)")
					.replaceAll("(?<!\\\\)%[\\.\\\\d]*f", "\\\\d*\\.\\\\d+")
					.replaceAll("(?<!\\\\)%n", "\\\\d+");
			// modification precaution: it has been tested, and hence learned,
			// the
			// double-escaping remains AS-IS
			// THIS IS THE ONLY PART OF THE FILE WHERE YOU NEED TO DOUBLE-SCAPE
			// tricky characters, if they're the only content: helps
			// avoid
			// false positives as a "." or a "*" alone, can match just anything.
			// Needless to say, these quantifiers, along with a "+" and an
			// optionality quantifier, i.e. a "?", might also cause
			// the memory heap to exceed
			// plus, HAD TO, since the intention is to handle both standard, and custom, format specifiers
			boolean strict = false;
			if (is(bools)) {
				strict = bools[0] == true;
			}
			Pattern pattern = Pattern.compile(re,
					strict ? 0 : Pattern.CASE_INSENSITIVE);
			Matcher matcher = pattern.matcher(str.trim());
			return !!matcher.find();
		} catch (IllegalArgumentException | StackOverflowError e) {
			return false;
		}
	}
	public static String findMatch(String str, String re, boolean... bools) {
		if (not(str) || not(re)) {
			return "";
		}
		if (re.equals(".") || re.equals("*") || re.equals("+") || re.equals("?")
				|| re.equals("^") || re.equals("$")) {
			re = "\\" + re; // escape special characters IF they're the only
							// content of the regexp, to avoid stack overflow
		}
		try {
			re = re.replaceAll("(?<![\\.\\\\])\\.(?![\\+\\*\\{])", "\\\\.")
					.replaceAll("(?<![\\\\\\.\\w\\)\\]\\|\\%\\$@])([\\+\\*])",
							"\\\\$1")
					.replaceAll("(?<!\\\\)%c", "[A-Za-z]")
					.replaceAll("(?<!\\\\)(%[sw]|\\{\\})", "[A-Za-z][\\\\w]+")
					.replaceAll("(?<!\\\\)%b", "(true|false)")
					.replaceAll("(?<!\\\\)%[di]", "(?<!\\.)\\\\d+(?!\\.)")
					.replaceAll("(?<!\\\\)%[\\.\\\\d]*f", "\\\\d*\\.\\\\d+")
					.replaceAll("(?<!\\\\)%n", "\\\\d+");
			// modification precaution: it has been tested, and hence learned,
			// the
			// double-escaping remains AS-IS
			// THIS IS THE ONLY PART OF THE FILE WHERE YOU NEED TO DOUBLE-SCAPE
			// tricky characters, if they're the only content: helps
			// avoid
			// false positives as a "." or a "*" alone, can match just anything.
			// Needless to say, these quantifiers, along with a "+" and an
			// optionality quantifier, i.e. a "?", might also cause
			// the memory heap to exceed
			// plus, HAD TO, since the intention is to handle both standard, and custom, format specifiers
			boolean strict = false;
			if (is(bools)) {
				strict = bools[0] == true;
			}
			Pattern pattern = Pattern.compile("(" + re + ")",
					strict ? 0 : Pattern.CASE_INSENSITIVE);
			Matcher matcher = pattern.matcher(str.trim());
			if (!matcher.find()) {
				return "";
			}
			return matcher.group();
		} catch (IllegalArgumentException | StackOverflowError e) {
			return "";
		}
	}
	public static String findMatch(String str, String re, String groupName) {
		if (not(str) || not(re) || not(groupName)) {
			return "";
		}
		if (re.equals(".") || re.equals("*") || re.equals("+") || re.equals("?")
				|| re.equals("^") || re.equals("$")) {
			re = "\\" + re; // escape special characters IF they're the only
							// content of the regexp, to avoid stack overflow
		}
		try {
			re = re.replaceAll("(?<![\\.\\\\])\\.(?![\\+\\*\\{])", "\\\\.")
					.replaceAll("(?<![\\\\\\.\\w\\)\\]\\|\\%\\$@])([\\+\\*])",
							"\\\\$1")
					.replaceAll("(?<!\\\\)%c", "[A-Za-z]")
					.replaceAll("(?<!\\\\)(%[sw]|\\{\\})", "[A-Za-z][\\\\w]+")
					.replaceAll("(?<!\\\\)%b", "(true|false)")
					.replaceAll("(?<!\\\\)%[di]", "(?<!\\.)\\\\d+(?!\\.)")
					.replaceAll("(?<!\\\\)%[\\.\\\\d]*f", "\\\\d*\\.\\\\d+")
					.replaceAll("(?<!\\\\)%n", "\\\\d+");
			// modification precaution: it has been tested, and hence learned,
			// the
			// double-escaping remains AS-IS
			// THIS IS THE ONLY PART OF THE FILE WHERE YOU NEED TO DOUBLE-SCAPE
			// tricky characters, if they're the only content: helps
			// avoid
			// false positives as a "." or a "*" alone, can match just anything.
			// Needless to say, these quantifiers, along with a "+" and an
			// optionality quantifier, i.e. a "?", might also cause
			// the memory heap to exceed
			// plus, HAD TO, since the intention is to handle both standard, and custom, format specifiers
			Pattern pattern = Pattern.compile("(" + re + ")",
					Pattern.CASE_INSENSITIVE);
			Matcher matcher = pattern.matcher(str.trim());
			if (!matcher.find()) {
				return "";
			}
			groupName = groupName.replaceAll("[\\$\\{\\}]", "");
			String acquiredValueFromTheGroup = isIntLike(groupName)
					? matcher.group(Int(groupName))
					: matcher.group(groupName);
			if (not(acquiredValueFromTheGroup))
				return "";
			//the null check is necessary
			return acquiredValueFromTheGroup;
		} catch (IllegalArgumentException | StackOverflowError e) {
			return "";
		}
	}
