		public static int indexOf(int[] src, int target) {
			if (src == null || src.length == 0)
				return -1;
			int[] arr = src.clone();
			java.util.Arrays.sort(arr);
			int low = 0, high = arr.length - 1;
			while (low <= high) {
				int mid = low + (high - low) / 2;
				if (arr[mid] == target)
					return mid;
				else if (arr[mid] < target)
					low = mid + 1;
				else
					high = mid - 1;
			}
			return -1;
		}
