	public static String sentCase(String input) {
		if (not(input)) {
			return "";
		}
		input = (input.toUpperCase().substring(0, 1)
				+ (!in(input, "[A-Z]{2,}") ? input.toLowerCase() : input)
						.substring(1))
				.replaceAll("(?<!\\w)i(?!\\w)", "I");
		input = Pattern.compile("(?<=\\.\\s)([A-Za-z])").matcher(input)
				.replaceAll(matches -> matches.group().toUpperCase());
		return input;
	}
	public static String[] sentCase(String... inputs) {
		if (not(inputs)) {
			return blank.Str;
		}
		inputs = map(inputs, KL::sentCase);
		return inputs;
	}
	public static String titleCase(String input) {
		if (not(input)) {
			return "";
		}
		String[] parts = input.split("");
		String result = "";
		boolean nextTitleCase = true;
		for (String c : parts) {
			if (eq(c, " ")) {
				nextTitleCase = true;
			} else if (nextTitleCase) {
				c = upper(c);
				nextTitleCase = false;
			}
			result += c;
		}
		return result;
	}
	public static String[] titleCase(String... inputs) {
		if (not(inputs)) {
			return blank.Str;
		}
		inputs = map(inputs, KL::titleCase);
		return inputs;
	}
	public static String title(String input) {
		return titleCase(input);
	}
	public static String[] title(String... inputs) {
		return titleCase(inputs);
	}
