	public static char[] charArrToCharArr(Character[] inputArr) {
		if (not(inputArr)) {
			return blank.Char;
		}
		int length = inputArr.length;
		char resultingArr[] = new char[length];
		for (int i = 0; i < length; i++) {
			resultingArr[i] = inputArr[i];
		}
		return resultingArr;
	}
